insert into exercises(id, team_id, place, phase, name, page, data) values
  ('ex01', null, 'grass', 'auf', 'Freies Kleinfeldspiel', '60', '{"org":"Zwei Kleinfelder ca. 25×15 m mit je zwei Minitoren, aufgebaut bevor das erste Kind kommt.","ablauf":"Wer ankommt, spielt sofort frei, vom 1:0 bis zum 4:4. Sind acht Kinder auf einem Feld, schickst du die nächsten ins zweite Feld.","coach":["Laufen lassen, noch nicht korrigieren","Ankommende Kinder kurz begrüssen"],"var":"Spielfeldgrösse der Anzahl Kinder anpassen.","d":{"s":"grass","items":[["area",6,3,88,27],["area",6,34,88,27],["m",6,16],["m",94,16,1],["m",6,47],["m",94,47,1],["A",34,12],["A",40,22,1],["B",58,14],["B",62,24],["A",30,44,1],["B",52,52],["drib",42,22,58,20],["shot",60,19,92,16],["shot",32,44,8,47]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Freies Kleinfeldspiel","url":"http://jsle.ch/dAfk"},{"title":"J+S-Video: Trainingsformen zum Auffangen","url":"http://jsle.ch/dVAu"}]}'::jsonb),
  ('ex02', null, 'grass', 'ein', 'Schatzinsel', '61', '{"org":"Feld 25×25 m, Insel in der Mitte, zwei Piratenschiffe in den Ecken. Jedes Kind mit Ball.","offen":"Bei «Ahoi, Piraten!» dribbeln alle zur Insel. Bei «Hejo, Captain Jack!» Ball liegen lassen und mit einem freien Ball weiterdribbeln.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist führen.","wett":"Piraten gegen Affen: Die Affen beschützen die Bälle auf der Insel, die Piraten entführen sie dribbelnd aufs Schiff. Affen dürfen Bälle zurückholen. Wer hat nach zwei Minuten mehr Bälle?","coach":["Heutiger Fokus liegt im Wetteifern: wie eine Wespe den Ball jagen (S. 42)","Nach dem Ballgewinn den Körper als Schutzschild einsetzen"],"var":"Mehr Affen macht es für die Piraten schwerer, eine grössere Insel leichter.","d":{"s":"grass","items":[["area",14,4,72,56],["zone",40,22,20,20,"Insel"],["zone",14,4,16,12,"Schiff"],["zone",70,48,16,12,"Schiff"],["B",45,28],["B",55,36],["ball",47,35],["ball",53,27],["ball",50,31],["A",32,22,1],["A",68,40,1],["A",28,44],["A",72,18],["drib",34,23,24,12],["drib",70,41,77,52],["run",55,36,66,42],["run",28,44,42,36]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}]}'::jsonb),
  ('ex03', null, 'grass', 'sp', 'Kleinfeldspiel 3:3 – Ab auf die andere Seite', '81 · 71', '{"org":"Zwei Felder 30×20 m mit Endzone an beiden Enden und je einem Minitor. 3:3 und 4:4.","offen":"Tore zählen nur aus der Endzone. Das Team, das trifft, bleibt im Ballbesitz und greift sofort in die andere Richtung an.","ueben":"Nach dem Tor sofort auf die neue Situation umschalten und den freien Raum nutzen.","wett":"Welchem Team gelingen zwei Tore in Folge?","coach":["Bei Ballgewinn die Blume öffnen, bei Ballverlust schliessen (S. 42)","Bei Fouls entscheiden die Kapitäne (S. 81)"],"var":"Tiefere Endzone erleichtert den Abschluss.","d":{"s":"grass","items":[["zone",0,0,14,64,"Endzone"],["zone",86,0,14,64,"Endzone"],["m",0,32],["m",100,32,1],["A",30,20],["A",46,44],["A",62,30],["B",72,18],["B",76,46],["B",40,32],["drib",62,32,88,36],["shot",90,36,99,33],["drib",90,40,60,52],["txt",50,62,"Nach dem Tor sofort zurück angreifen"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Kleinfeldspiel 3:3","url":"http://jsle.ch/d3v3"},{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}]}'::jsonb),
  ('ex04', null, 'grass', 'le', '1:1 mit Umschalten', '68', '{"org":"Zwei Stationen à 7 Kinder: grosses Tor mit Torhüter/in, Schusszone vor dem Tor, Startreihe ca. 25 m entfernt.","offen":"Ein Kind dribbelt Richtung Schusszone und versucht im 1:1 ein Tor zu erzielen. Nach dem Abschluss verteidigt es selbst, das nächste Kind startet sofort.","ueben":"Situation sofort wahrnehmen, mit Tempo und Richtungswechseln zum Tor; danach rasch die Verteidigerrolle einnehmen.","wett":"Zwei Teams: Welches erzielt mehr Tore? Nach einem Durchgang die Seiten wechseln.","coach":["Vor dem Tor entschlossen wie eine Raubkatze (S. 75)","Vor dem Schiessen ein Foto vom Tor machen","Als Verteidiger/in wie eine Wespe den Ball jagen"],"var":"Schusszone näher am Start macht es leichter, ein früherer Start des Verteidigers schwerer.","d":{"s":"grass","items":[["zone",70,12,18,40,"Schusszone"],["G","R"],["B",97,32],["A",8,28],["A",8,36],["A",4,32],["A",22,32,1],["B",80,44],["drib",24,32,66,31],["run",80,44,70,36],["shot",72,30,98,28],["txt",12,46,"Startreihe"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Dribbling","url":"http://jsle.ch/dDrB"}]}'::jsonb),
  ('ex05', null, 'grass', 'vi', 'Jäger und Hase', '80', '{"org":"Paare. Jagdzone ca. 10×10 m, am Ende ein rotes und ein gelbes Tor aus Hütchen.","offen":"Auf ein Signal startet der Hase in die Jagdzone, gleichzeitig rennt der Jäger los. Je nach Jäger sprintet der Hase durchs rote oder gelbe Tor, der Jäger versucht ihn zu berühren. Dann Rollen tauschen.","ueben":"Mit einer überraschenden Körpertäuschung den Jäger überlisten.","wett":"Welcher Hase sammelt die meisten Punkte? Welcher Jäger schlägt fünf Hasen?","coach":["Täuschen und schlau sein wie ein Fuchs"],"var":"Breitere Jagdzone erleichtert es dem Hasen.","d":{"s":"grass","items":[["area",28,8,40,48],["c",68,12],["c",68,24],["c",68,40],["c",68,52],["txt",76,19,"rot"],["txt",77,47,"gelb"],["A",22,32],["B",48,4],["run",24,32,48,34],["run",48,34,67,46],["run",48,6,58,38]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Vielseitigkeit erleben","url":"http://jsle.ch/dVVe"}]}'::jsonb),
  ('ex06', null, 'grass', 'sp', 'Der Match – Grossfeld', '81', '{"org":"Grossfeld mit zwei grossen Toren, maximal 6:6 inkl. Torhüter/in. Bei 14 Kindern rotieren zwei Kinder auf dein Signal ein, alle spielen gleich lang.","ablauf":"Die Kinder bilden selbst ausgeglichene Teams, bestimmen Kapitäne, machen eine Grundordnung und starten das Spiel selbstständig.","coach":["Erobern wie eine Wespe, abschliessen wie eine Raubkatze","Shakehands nach dem Schlusspfiff"],"var":"","d":{"s":"grass","full":1,"items":[["G","L"],["G","R"],["A",3,32],["A",22,18],["A",22,46],["A",40,32],["A",58,20,1],["A",60,44],["B",97,32],["B",78,18],["B",78,46],["B",64,30],["B",46,48],["B",44,16],["run",64,30,60,24],["drib",60,20,74,22],["shot",76,23,98,29]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Der Match","url":"http://jsle.ch/dfDM"},{"title":"J+S-Video: Trainingsformen zum Hauptteil Fussball spielen","url":"http://jsle.ch/dvFS"}]}'::jsonb),
  ('ex07', null, 'grass', 'aus', 'Penalty-König/in', '82', '{"org":"Ein grosses Tor, Torhüter/in wechselt.","ablauf":"Abwechselnd Penaltys, jedes Tor ein Punkt. 1. Durchgang links, 2. Durchgang rechts, 3. Durchgang freie Wahl. Wer hat nach drei Durchgängen am meisten Tore? Danach Schlusswort und persönliche Verabschiedung.","coach":["Alle bleiben dabei, niemand scheidet aus (S. 52)"],"var":"","d":{"s":"grass","items":[["zone",80,16,20,32,""],["G","R"],["B",97,32],["ball",88,32],["A",70,32],["A",66,28],["A",66,36],["A",62,32],["run",72,32,86,32],["shot",88,32,98,28]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Penalty-König/in","url":"http://jsle.ch/dPen"},{"title":"J+S-Video: Trainingsformen zum Ausklang","url":"http://jsle.ch/dvTA"}]}'::jsonb),
  ('ex08', null, 'grass', 'auf', 'Kickstart', '60', '{"org":"Mindestens sechs Minitore stehen bereit.","ablauf":"Wer ankommt, nimmt einen Ball und schiesst auf verschiedene Tore oder absolviert selbstständig einen Torschussrundlauf.","coach":["Vor dem Schuss ein Foto vom Tor machen"],"var":"Distanz zu den Toren verändern.","d":{"s":"grass","items":[["m",10,12],["m",10,32],["m",10,52],["m",90,12,1],["m",90,32,1],["m",90,52,1],["A",40,20,1],["A",58,40,1],["A",46,48,1],["B",60,18],["shot",42,20,88,13],["shot",57,41,12,51],["drib",48,48,62,52]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Auffangen","url":"http://jsle.ch/dVAu"}]}'::jsonb),
  ('ex09', null, 'grass', 'ein', 'Passduell', '62', '{"org":"Inneres Feld ca. 15×15 m für Tandems, aussen herum ein Dribbel-Parcours. Zwei Teams à 7.","offen":"Ein Team dribbelt aussen durch den Parcours, das andere passt sich im inneren Feld in Tandems die Bälle zu. Danach wechseln.","ueben":"Annehmen, vorlegen, zuspielen (drei Kontakte); Distanz variieren; nur links, nur rechts.","wett":"Wie viele Pässe schaffen die Tandems, bis alle Kinder den Parcours absolviert haben?","coach":["Fuss als Golfschläger: fest anspannen und ausdrehen (S. 70)","Vor dem Pass ein Foto vom Ziel machen"],"var":"Distanz zwischen den Tandems verändern.","d":{"s":"grass","items":[["area",34,16,32,32],["c",18,8],["c",40,6],["c",60,8],["c",82,6],["c",88,32],["c",82,58],["c",60,56],["c",40,58],["c",18,56],["c",12,32],["A",40,24],["A",58,24,1],["A",42,40,1],["A",60,42],["pass",56,24,42,24],["pass",44,40,58,41],["B",28,8,1],["B",88,20,1],["B",50,58,1],["drib",30,8,48,8],["drib",88,22,88,44]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Passduell","url":"http://jsle.ch/dpaS"},{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}]}'::jsonb),
  ('ex10', null, 'grass', 'sp', 'Kleinfeldspiel 3:3 – Torspieler/in in der Abschlusszone', '81 · 76', '{"org":"Zwei Felder 30×20 m, an jeder Stirnseite zwei Minitore in den Ecken mit Abschlusszone davor. 3:3 plus je ein/e Torspieler/in, Torspieler/in wechselt nach jedem Gegentor.","offen":"Die Torspieler/innen dürfen den Ball in der Abschlusszone mit den Händen abwehren.","ueben":"Mit rascher Spielverlagerung die Breite nutzen und aufs freie Tor abschliessen. Als Torspieler/in rasch verschieben.","wett":"Welche/r Torspieler/in bekommt am wenigsten Tore?","coach":["Blume öffnen: breit stehen, damit das freie Tor aufgeht"],"var":"Breiteres Feld gibt mehr Raum für die Verlagerung.","d":{"s":"grass","items":[["zone",0,0,12,64,"Zone"],["zone",88,0,12,64,"Zone"],["m",0,12],["m",0,52],["m",100,12,1],["m",100,52,1],["A",6,32],["B",94,48],["A",48,48,1],["A",64,14],["A",36,24],["B",70,44],["B",56,36],["B",40,40],["pass",50,47,63,16],["shot",66,14,99,12],["txt",50,62,"Verlagern auf das freie Tor"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Kleinfeldspiel 3:3","url":"http://jsle.ch/d3v3"},{"title":"J+S-Video: Trainingsformen zum Torabschluss","url":"http://jsle.ch/dTor"}]}'::jsonb),
  ('ex11', null, 'grass', 'le', 'Angreifen in Überzahl – 3:1', '72', '{"org":"Zwei Felder 30×20 m mit Mittellinie und zwei Minitoren an der Stirnseite. Pro Feld drei Angreifer/innen und ein/e Verteidiger/in, Rollen rotieren.","offen":"Team Weiss greift im 3:1 (oder 2:1) auf die beiden Tore an. Geschossen wird ab der Mittellinie. Ist der Ball im Tor oder im Aus, ist der Angriff zu Ende.","ueben":"Mit Zusammenspiel oder Dribbling die Verteidigung ausspielen und entschlossen den Abschluss suchen.","wett":"Schafft das angreifende Team aus acht Versuchen vier Tore?","coach":["Breite und Tiefe: Anspielstationen vorne, hinten und seitlich (Rhombus, Dreieck) (S. 42)","Aus dem Schatten in die Sonne laufen"],"var":"Leichter: 3:0 mit 5–10 Sekunden Zeit. Schwerer: 3:2 (beide S. 72). Stellschraube «Anzahl Spieler».","d":{"s":"grass","items":[["line",50],["m",100,18,1],["m",100,46,1],["A",36,10],["A",36,32,1],["A",36,54],["B",72,32],["run",36,10,66,12],["pass",38,32,64,13],["run",36,54,66,52],["shot",68,13,98,18],["txt",50,62,"Schuss ab der Mittellinie"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}]}'::jsonb),
  ('ex12', null, 'grass', 'vi', 'Hüpfen rund um die Welt', '80', '{"org":"Markiertes Feld mit farbigen Reifen.","offen":"Frei im Feld bewegen und immer wieder ein- und beidbeinig in die Reifen hüpfen, zuerst allein, dann zu zweit: Eines hüpft vor, das andere nach.","ueben":"Reifen nicht berühren und auf dem Vorderfuss springen wie eine Gazelle.","wett":"Wer schafft es ohne Fehler? Stafette mit gleicher Hüpfabfolge oder eigene Abfolgen erfinden lassen.","coach":["Leicht und federnd landen"],"var":"Reifen weiter auseinander legen macht es schwerer.","d":{"s":"grass","items":[["area",14,6,72,52],["hoop",28,18],["hoop",40,26],["hoop",52,16],["hoop",64,28],["hoop",72,44],["hoop",56,46],["hoop",36,44],["hoop",24,34],["A",20,22],["A",48,36],["B",62,54],["run",22,22,38,25],["run",48,36,55,44]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Hüpfen rund um die Welt","url":"http://jsle.ch/dVhw"},{"title":"J+S-Video: Vielseitigkeit erleben","url":"http://jsle.ch/dVVe"}]}'::jsonb),
  ('ex13', null, 'grass', 'aus', 'Linienschiessen', '82', '{"org":"Ein grosses Tor, Markierungen in steigender Distanz.","ablauf":"Aus einer Distanz den Ball in der Luft ins Tor schiessen. Wer trifft, geht zur nächsten, weiter entfernten Markierung, wer nicht trifft, bleibt. Wer trifft wie oft? Danach Schlusswort und Verabschiedung.","coach":["Fragen an die Kinder stellen (siehe oben)"],"var":"","d":{"s":"grass","items":[["G","R"],["c",82,14],["c",82,50],["c",72,14],["c",72,50],["c",62,14],["c",62,50],["A",82,30],["A",72,36],["A",62,26],["shot",83,30,98,31],["shot",73,36,98,34]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Linienschiessen","url":"http://jsle.ch/dLiS"},{"title":"J+S-Video: Trainingsformen zum Ausklang","url":"http://jsle.ch/dvTA"}]}'::jsonb),
  ('ex14', null, 'hall', 'auf', 'Fangis', '60', '{"org":"Ein Fangisfeld steht bereit.","ablauf":"Wer kommt, spielt selbstständig ein Fangis nach Wahl. Jedes Kind darf einmal Fänger/in sein.","coach":["Ältere Kinder toben sich gern in Fang- und Laufspielen aus (S. 37)"],"var":"Feldgrösse an die Anzahl Kinder anpassen.","d":{"s":"hall","items":[["area",14,6,72,52],["B",48,30],["A",30,18],["A",66,20],["A",34,44],["A",64,46],["run",48,30,36,42],["run",34,44,22,52]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Auffangen","url":"http://jsle.ch/dVAu"}]}'::jsonb),
  ('ex15', null, 'hall', 'ein', 'Spiel mit dem Feuer', '64', '{"org":"Halbe Halle, jedes Kind mit Ball. Zwei Kinder sind das «Feuer» (Überzieher).","offen":"Die Feuer versuchen, dribbelnde Kinder zu berühren. Wer sich verbrennt, erfüllt eine Aufgabe oder umdribbelt das Spielfeld.","ueben":"Dribbling mit beiden Füssen, Innen- und Aussenfuss; Finten wie Körpertäuschung, Übersteiger oder Schere.","wett":"Welches Feuer erwischt in einer Minute am meisten Kinder?","coach":["Den Ball als Hund bei Fuss halten (S. 42)","Mit Finten ausweichen, schlau wie ein Fuchs"],"var":"Mehr Feuer machen es schwerer.","d":{"s":"hall","items":[["area",10,6,80,52],["B",46,26],["B",62,40],["A",24,18,1],["A",70,16,1],["A",30,44,1],["A",54,50,1],["A",76,34,1],["A",40,34,1],["run",46,26,40,32],["drib",40,34,28,38],["run",62,40,54,48]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}]}'::jsonb),
  ('ex16', null, 'hall', 'sp', 'Kleinfeldspiel 3:3', '81', '{"org":"Halle quer in zwei Kleinfelder teilen, je zwei Minitore oder umgekippte Langbänke. 3:3 und 4:4.","ablauf":"Freies Spiel. Die Kinder bilden die Teams selbst und lösen Fouls über die Kapitäne.","own":"Eigene Zusatzregel (nicht im Manual): Ein Tor direkt nach Ballgewinn zählt doppelt.","coach":["Nach Ballverlust sofort jagen wie eine Wespe","Nach Ballgewinn Blume öffnen"],"var":"Kleineres Feld bringt mehr Duelle.","d":{"s":"hall","items":[["line",50],["m",0,32],["m",50,32,1],["m",50,32],["m",100,32,1],["A",14,22],["A",22,42,1],["A",34,30],["B",40,20],["B",36,44],["B",28,30],["run",28,30,22,40],["A",64,24],["A",72,42],["A",80,30],["B",86,20],["B",88,44],["B",70,32,1],["drib",70,34,92,34],["shot",93,34,99,32]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Kleinfeldspiel 3:3","url":"http://jsle.ch/d3v3"}]}'::jsonb),
  ('ex17', null, 'hall', 'le', '1:1 mit acht Toren', '69', '{"org":"Zwei parallele Bahnen ca. 20×12 m, an jedem Ende zwei Minitore mit Abschlusszone (acht Tore). Team Rot und Team Weiss stehen sich gegenüber.","offen":"Zwei Kinder von Rot dribbeln gleichzeitig ins Feld und passen auf die andere Seite zur Gegenspielerin oder zum Gegenspieler. Danach folgt das 1:1 auf die beiden Minitore. Erobert Rot den Ball zurück, kontert es auf die gegenüberliegenden Minitore. Tore zählen nur aus der Abschlusszone.","ueben":"Nach erfolgreicher Ballkontrolle schnell Richtung Minitore dribbeln, mit Richtungswechsel oder gut getimter Finte austricksen und abschliessen.","wett":"Jedes Kind hat drei Versuche. Wer erzielt mehr Tore?","coach":["Verteidigen wie eine Wespe, nach Ballgewinn sofort kontern","Vor dem Tor entschlossen wie eine Raubkatze"],"var":"Schmalere Bahn macht es für den Angreifer schwerer.","d":{"s":"hall","items":[["area",4,3,92,26],["area",4,35,92,26],["zone",4,3,12,26,""],["zone",84,3,12,26,""],["zone",4,35,12,26,""],["zone",84,35,12,26,""],["m",4,9],["m",4,23],["m",96,9,1],["m",96,23,1],["m",4,41],["m",4,55],["m",96,41,1],["m",96,55,1],["A",24,12],["B",78,12],["pass",26,12,76,12],["drib",78,18,30,22],["run",26,14,36,20],["A",40,48,1],["B",34,54],["drib",42,48,80,46],["shot",82,46,95,42],["txt",60,58,"Ballgewinn = Konter"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Dribbling","url":"http://jsle.ch/dDrB"}]}'::jsonb),
  ('ex18', null, 'hall', 'vi', 'Feuerball (Tupfball)', '80', '{"org":"Vierecke ca. 8×8 m. Pro Viereck ein Dreierteam und ein «Eisbär» des anderen Teams.","offen":"Das Dreierteam spielt sich den Ball mit den Händen zu und versucht, den Eisbären mit dem Ball zu berühren, nicht abzuschiessen. Mit dem Ball in der Hand darf man nicht laufen.","ueben":"Mit raschem Zusammenspiel den Eisbären in die Ecke drängen.","wett":"Welches Team erzielt mehr Punkte? Welcher Eisbär kann sich freilaufen?","coach":["Gemeinsam im Schwarm jagen, wie beim Erobern im Fussball"],"var":"Grösseres Viereck erleichtert es dem Eisbären.","d":{"s":"hall","items":[["area",8,8,36,48],["area",56,8,36,48],["A",12,12,1],["A",40,22],["A",18,50],["B",28,34],["pass",14,14,38,21],["A",60,14],["A",88,20,1],["A",66,52],["B",76,36],["pass",86,22,77,34]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Feuerball (Tupfball)","url":"http://jsle.ch/dFeB"},{"title":"J+S-Video: Vielseitigkeit erleben","url":"http://jsle.ch/dVVe"}]}'::jsonb),
  ('ex19', null, 'hall', 'sp', 'Der Match – Hallen-Grossfeld', '81', '{"org":"Ganze Halle, zwei Handballtore, maximal 6:6 inkl. Torhüter/in. Zwei Kinder rotieren auf Signal ein.","ablauf":"Die Kinder starten selbstständig und spielen fair.","coach":["Als Bienen ausschwärmen: alle beteiligen sich (S. 42)","Nach Ballgewinn sofort die Blume öffnen"],"var":"","d":{"s":"hall","full":1,"items":[["G","L"],["G","R"],["A",3,32],["A",22,18],["A",22,46],["A",40,32],["A",58,20,1],["A",60,44],["B",97,32],["B",78,18],["B",78,46],["B",64,30],["B",46,48],["B",44,16],["run",64,30,60,24],["drib",60,20,74,22],["shot",76,23,98,29]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Der Match","url":"http://jsle.ch/dfDM"},{"title":"J+S-Video: Trainingsformen zum Hauptteil Fussball spielen","url":"http://jsle.ch/dvFS"}]}'::jsonb),
  ('ex20', null, 'hall', 'aus', 'Schiessbude', '82', '{"org":"Mit dem gesamten Trainingsmaterial baust du im Tor eine Schiessbude auf.","ablauf":"Wer trifft am meisten Gegenstände? Danach Schlusswort, Verabschiedung und gemeinsamer Abbau.","coach":["Alle helfen beim Auf- und Abbau (S. 52)"],"var":"","d":{"s":"hall","items":[["G","R"],["c",97,28],["c",97,32],["c",97,36],["box",92,24,3,3,""],["box",92,37,3,3,""],["A",70,22,1],["A",68,32,1],["A",70,42,1],["shot",72,22,96,27],["shot",70,32,96,32]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Ausklang","url":"http://jsle.ch/dvTA"}]}'::jsonb),
  ('ex21', null, 'hall', 'auf', 'Dribblestart', '60', '{"org":"Ein Feld mit unterschiedlichen Gegenständen steht bereit (Kegel, Reifen, Langbank, Kastenteil).","ablauf":"Wer kommt, schnappt sich einen Ball und umdribbelt die Gegenstände.","coach":["Wer früh da ist, hilft beim Aufbau"],"var":"Gegenstände enger stellen macht es schwerer.","d":{"s":"hall","items":[["c",22,14],["c",40,46],["c",70,18],["hoop",54,30],["hoop",28,40],["bench",60,48,22,4,"Langbank"],["box",80,26,8,10,"Kasten"],["A",34,24,1],["A",62,30,1],["A",48,52,1],["drib",36,24,24,18],["drib",62,32,76,30]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zum Auffangen","url":"http://jsle.ch/dVAu"}]}'::jsonb),
  ('ex22', null, 'hall', 'ein', 'Toblerone', '62', '{"org":"Drei Teams à 4–5, vier markierte Dreiecke (eines bleibt frei). Jedes Kind mit Ball.","offen":"Jedes Kind dribbelt im Dreieck seines Teams. Auf dein Zeichen wechselt das ganze Team in ein freies Dreieck.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist führen.","wett":"Welches Team ist zuerst vollzählig im freien Dreieck? Oder: Welches Team ist zuerst wieder im Startdreieck, nachdem es alle anderen besucht hat?","coach":["Rundumblick: alle Mitspielenden sehen (S. 42)"],"var":"Dreiecke weiter auseinander bedeutet längere Wege.","d":{"s":"hall","items":[["c",10,8],["c",34,8],["c",22,28],["c",66,8],["c",90,8],["c",78,28],["c",10,56],["c",34,56],["c",22,36],["c",66,56],["c",90,56],["c",78,36],["A",18,14,1],["A",26,16,1],["B",74,14,1],["B",82,16,1],["N",18,50,1],["N",26,48,1],["drib",28,48,66,50],["txt",78,50,"frei"]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}]}'::jsonb),
  ('ex23', null, 'hall', 'sp', 'Kleinfeldspiel 3:3 – In die Endzone', '81 · 65', '{"org":"Halle quer in zwei Felder, an beiden Enden eine Endzone (3–4 m). 3:3 und 4:4.","offen":"Einen Punkt erhält, wer in die Endzone gelangt und den Ball dort stoppen kann.","ueben":"Mutig in die Endzone dribbeln, freilaufen, anspielbar sein (in die Sonne) und passen; Blume öffnen und schliessen.","wett":"Welches Team schafft es von Endzone zu Endzone ohne Ballverlust?","own":"Eigener Tipp: In die Tiefe starten, wenn der Passgeber den Kopf hebt.","coach":["Mit dem Ball als Sonne aus dem Schatten heraustreten (S. 42)"],"var":"Schmalere Endzone macht es schwerer.","d":{"s":"hall","items":[["zone",0,0,12,64,"Endzone"],["zone",88,0,12,64,"Endzone"],["A",24,22],["A",34,46],["A",62,30,1],["A",70,10],["B",78,26],["B",70,46],["B",50,20],["run",70,10,93,20],["pass",64,29,92,22]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Kleinfeldspiel 3:3","url":"http://jsle.ch/d3v3"},{"title":"J+S-Video: Trainingsformen zum Dribbling","url":"http://jsle.ch/dDrB"}]}'::jsonb),
  ('ex24', null, 'hall', 'le', 'Drei Aussenspieler/innen', '71', '{"org":"Feld ca. 30×20 m mit zwei Toren. 3:3 im Feld, pro Team drei Aussenspieler/innen an den Linien, die übrigen zwei Kinder sind Torhüter/innen.","offen":"Die Teams können ihre Aussenspieler/innen jederzeit anspielen. Spielen diese direkt zurück, bleiben sie aussen. Nehmen sie den Ball an und laufen ins Feld, übernimmt der Passgeber ihre Rolle.","ueben":"Die Satelliten in der Breite und der Tiefe einbeziehen; als Aussenspieler/in den Ball kontrolliert ins Feld mitnehmen und entschlossen abschliessen.","wett":"Welches Team erzielt in 3 Minuten mehr Tore?","coach":["Blume öffnen bei eigenem Ballbesitz (S. 70)","Vor dem Pass ein Foto vom Ziel machen"],"var":"Aussenspieler/innen nur mit Direktspiel ist schwerer, mit zwei Kontakten leichter.","d":{"s":"hall","items":[["G","L"],["G","R"],["A",3,32],["B",97,32],["A",24,0],["A",74,0],["A",50,64],["B",24,64],["B",74,64],["B",50,0],["A",44,30,1],["A",60,40],["A",34,46],["B",56,22],["B",68,34],["B",40,40],["pass",46,28,26,2],["drib",26,3,62,18],["shot",64,20,98,29]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}]}'::jsonb),
  ('ex25', null, 'hall', 'vi', 'Tannenbaum-Fangis', '80', '{"org":"Halbe Halle, zwei Fänger/innen.","offen":"Wer berührt wird, steht wie eine Tanne (Arme ausgestreckt, breitbeinig). Befreit wird, wer von einem anderen Kind zwischen den Beinen durchkrochen wird.","ueben":"Als Fänger/innen gemeinsam eine Strategie festlegen.","wett":"Schaffen es die Fänger/innen, alle zu fangen? Wer befreit fünf Tannen?","coach":["Rennen, Ausweichen, Kriechen: vielseitig bewegen"],"var":"Drei Fänger/innen machen es schwerer.","d":{"s":"hall","items":[["area",10,6,80,52],["B",40,24],["B",64,40],["A",30,40],["A",70,18],["A",52,30],["A",22,18],["txt",30,48,"Tanne"],["run",40,24,48,28],["run",22,18,28,36]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Tannenbaum-Fangis","url":"http://jsle.ch/dTan"},{"title":"J+S-Video: Vielseitigkeit erleben","url":"http://jsle.ch/dVVe"}]}'::jsonb),
  ('ex26', null, 'hall', 'aus', 'Bowling', '82', '{"org":"Paare mit vier Markierkegeln und einem Ball, fünf Meter Abstand.","ablauf":"Abwechselnd versucht ein Kind, die Kegel mit einem Pass umzuwerfen. Wie viele Versuche braucht das Paar für alle vier? Danach Schlusswort und gegenseitige Verabschiedung.","coach":["Fragen an die Kinder stellen (siehe oben)"],"var":"","d":{"s":"hall","items":[["c",70,14],["c",72,18],["c",70,22],["c",72,26],["A",40,20,1],["A",84,20],["pass",42,20,68,19],["c",70,40],["c",72,44],["c",70,48],["c",72,52],["B",40,46,1],["B",84,46],["pass",42,46,68,45]]},"src":"J+S-Manual Fussball Kinder","videos":[{"title":"J+S-Video: Bowling","url":"http://jsle.ch/dBow"},{"title":"J+S-Video: Trainingsformen zum Ausklang","url":"http://jsle.ch/dvTA"}]}'::jsonb),
  ('ex27', null, 'grass', 'ein', 'Tetris', 'Karte E1', '{"src":"SFV Trainingskarten Kat. E, Training 1","org":"Drei markierte Felder nebeneinander, je 20 × 15 m, mit Stangen, Reifen und Markierungen als Hindernisse. Jedes Kind hat einen Ball.","offen":"Jedes Kind dribbelt mit einem Ball in einem markierten Feld. Hebt der Trainer den Arm, wechseln die Kinder ins nächste Feld.","ueben":"Mit dem linken/rechten Fuss, Aussen-/Innenrist, seitwärts, rückwärts, Finte, den Ball über die Stangen heben etc.","wett":"2 bis 3 Fänger bestimmen. Kann ein Fänger einen Ball erobern oder gelangt der Ball aus dem Viereck, werden die Rollen getauscht. Die Fänger dürfen die Hindernisse nicht überschreiten. Danach in den anderen Feldern wiederholen.","coach":["Den Ball eng am Fuss führen, Kopf hoch"],"var":"Spielfeldgrösse 20 × 15 m. Mehr Fänger oder kleineres Feld macht es schwerer.","d":{"s":"grass","items":[["area",2,6,30,52],["area",35,6,30,52],["area",68,6,30,52],["c",10,20],["c",24,44],["hoop",18,32],["hoop",50,20],["c",44,46],["c",58,30],["hoop",80,44],["c",76,18],["c",90,30],["A",8,12,1],["A",26,26,1],["A",12,50,1],["A",45,30,1],["A",56,50,1],["A",74,30,1],["A",88,50,1],["B",20,40],["B",84,22],["drib",10,14,22,20],["drib",47,32,56,40],["run",20,40,14,48],["txt",50,62,"Arm hoch = Feld wechseln"]]},"videos":[]}'::jsonb),
  ('ex28', null, 'grass', 'le', 'Basis Torschuss', 'Karte E1', '{"src":"SFV Trainingskarten Kat. E, Training 1","org":"Feld 30 × 20 m mit zwei Toren und Torhütern. Vor jedem Tor eine Schusszone, davor eine orange Markierung. Die Kinder stehen in zwei Reihen.","offen":"Simon dribbelt zur orangen Markierung, macht eine Finte, legt sich den Ball in die Schusszone vor und versucht, mit dem rechten Fuss ein Tor zu erzielen. Er holt den Ball und schliesst auf der anderen Seite hinten an. Laura startet, sobald Simon sich den Ball vorgelegt hat.","ueben":"Beidseitiger Abschluss mit dem Innenrist oder Vollrist.","wett":"Welches Team erzielt innerhalb von 5 Minuten mehr Tore?","coach":["Tipp: Mit einem zweiten Tor die Wartezeiten reduzieren und die Bewegungszeit erhöhen"],"var":"Einfacher: Schusszone näher beim Tor oder vergrössern. Schwieriger: Schusszone weiter weg vom Tor oder verkleinern.","d":{"s":"grass","items":[["G","L"],["G","R"],["B",3,32],["B",97,32],["zone",70,22,14,20,"Schusszone"],["zone",16,22,14,20,"Schusszone"],["c",58,32],["c",42,32],["A",44,8,1],["A",40,8],["A",36,8],["A",56,56,1],["A",60,56],["A",64,56],["drib",46,10,57,29],["drib",59,33,72,32],["shot",76,32,98,29],["drib",54,54,43,35],["drib",41,33,28,32],["shot",24,32,2,35],["txt",58,40,"Finte"]]},"videos":[]}'::jsonb),
  ('ex29', null, 'grass', 'vi', 'Hasenjagd', 'Karte E1', '{"src":"SFV Trainingskarten Kat. E, Training 1","org":"Mehrere Vierecke 10 × 10 m. Pro Viereck ein 3er-Team und ein Gegenspieler aus einem anderen Team als Hase. Ein Ball (mit den Händen gespielt).","offen":"Das 3er-Team spielt sich den Ball mit den Händen so zu, dass ein Teammitglied den Hasen mit dem Ball berühren kann: 1 Punkt. Nicht abschiessen, kein Laufen mit dem Ball. Verlässt der Hase das Viereck, gibt es ebenfalls 1 Punkt.","ueben":"Nun versucht das 3er-Team, mit einer optimalen Feldbesetzung (Blume offen) und aktivem Suchen des Hasen Punkte zu erzielen.","wett":"Welcher Hase wurde am wenigsten getroffen?","coach":["Blume öffnen: Viereck breit besetzen"],"var":"Grösseres Viereck macht es für den Hasen leichter.","d":{"s":"grass","items":[["area",4,18,28,28],["area",36,18,28,28],["area",68,18,28,28],["A",8,22,1],["A",28,24],["A",14,42],["B",20,32],["pass",10,23,26,24],["A",40,22],["A",60,26,1],["A",46,42],["B",52,30],["pass",58,28,47,40],["A",72,24],["A",92,22],["A",84,42,1],["B",80,32],["run",80,32,74,38],["txt",50,58,"Ball mit den Händen · Hase abtupfen"]]},"videos":[]}'::jsonb),
  ('ex30', null, 'grass', 'sp', '5 gegen 5 / 1 gegen 1', 'Karte E1–E3', '{"src":"SFV Trainingskarten Kat. E, Training 1–3","org":"Grosses Feld 30 × 20 m mit zwei grossen Toren für 5 gegen 5. Daneben ein Nebenfeld 15 × 10 m mit Mini-Toren für 1 gegen 1.","ablauf":"Die Kinder spielen einen Match 5 gegen 5 auf grosse Tore. Auf dem Nebenfeld duellieren sich Kinder 1 gegen 1. Nach 3 Minuten wechseln die Kinder auf das grosse Feld. Die Sieger der Matches auf dem kleinen Feld bekommen pro Tor 1 Punkt für ihr Team. 7 Runden à 3 Minuten.","coach":["Alle spielen gleich lang, regelmässig wechseln","Shakehands nach dem Spiel"],"var":"","d":{"s":"grass","items":[["area",2,4,62,56],["G","L"],["m",64,32,1],["B",3,32],["A",16,18],["A",20,44],["A",32,30,1],["A",44,16],["B",48,42],["B",40,24],["B",52,32],["B",28,50],["area",70,8,28,22],["m",70,19],["m",98,19,1],["A",80,16,1],["B",88,22],["area",70,36,28,22],["m",70,47],["m",98,47,1],["A",78,44],["B",90,50,1],["drib",34,30,50,34],["txt",32,62,"5 gegen 5"],["txt",84,62,"1 gegen 1"]]},"videos":[]}'::jsonb),
  ('ex31', null, 'grass', 'le', '2 gegen 1 / 3 gegen 1 / 3 gegen 2', 'Karte E2', '{"src":"SFV Trainingskarten Kat. E, Training 2","org":"Feld 20 × 15 m mit zwei Toren und Torhütern. Zwei Teams, die hinter den Toren bzw. seitlich warten.","offen":"Simon spielt einen Pass zu Laura. Sie versucht, zusammen mit Erdan gegen Simon ein Tor zu erzielen. Das Spiel ist zu Ende, wenn ein Tor fällt oder der Ball im Aus ist. Die drei schliessen wieder bei ihrem Team an. 2 Runden à 5 Minuten, danach Rollenwechsel.","ueben":"Mutig nach vorne dribbeln und passen.","wett":"Welches Team erzielt innerhalb von 5 Minuten mehr Tore?","coach":["Tipp: Torspieler regelmässig wechseln"],"var":"Einfacher: Feld breiter, am Anfang ohne Pass vom Verteidiger. Schwieriger: Torschuss erst ab Mittellinie. Mehr Spieler: 3 gegen 1, 3 gegen 2.","d":{"s":"grass","items":[["G","L"],["G","R"],["B",3,32],["B",97,32],["line",50],["B",90,8],["B",94,8],["A",8,56],["A",12,56],["B",86,12,1],["pass",84,14,22,22],["A",20,22],["A",18,44],["drib",22,22,46,26],["run",18,44,60,40],["run",84,12,66,28],["pass",48,27,60,38],["shot",62,38,98,34]]},"videos":[]}'::jsonb),
  ('ex32', null, 'grass', 'vi', 'Wer hat Glück?', 'Karte E2', '{"src":"SFV Trainingskarten Kat. E, Training 2","org":"Feld 15 × 15 m. Zwei Fänger, alle anderen bewegen sich frei.","offen":"Wird jemand gefangen, gibt er dem Fänger die Hand, und sie fangen als Paar. Sind sie zu viert, lösen sich zwei und fangen zu zweit weiter.","ueben":"Mit den Kindern besprechen, wie sich die Fänger verhalten sollten, damit sie alle fangen können. Versuchen, dies umzusetzen.","wett":"Von Anfang an zwei Paare als Fänger. Fängt ein Paar ein Kind, fragen alle laut «Wer – hat – Glück?» und zeigen einen oder zwei Finger. Haben zwei Kinder gleich viele Finger, sind sie die neuen Fänger, das dritte Kind ist befreit.","coach":["Als Fängerpaar gemeinsam Wege abschneiden"],"var":"Grösseres Feld erleichtert es den Gejagten.","d":{"s":"grass","items":[["area",20,6,60,52],["B",40,26],["B",43,28],["B",64,44],["B",67,42],["A",28,14],["A",56,16],["A",72,22],["A",30,46],["A",50,38],["A",74,52],["A",34,30],["run",42,28,32,32],["run",66,43,56,38],["run",50,38,58,30],["txt",50,62,"Fänger halten sich an der Hand"]]},"videos":[]}'::jsonb),
  ('ex33', null, 'grass', 'aus', 'Balltransport', 'Karte E3', '{"src":"SFV Trainingskarten Kat. E, Training 3","org":"Zwei Teams sitzen je in einer Reihe hintereinander. Eine Ziellinie vor jeder Reihe.","ablauf":"Das vorderste Kind gibt den Ball über den Kopf rückwärts an das nächste weiter. Erreicht der Ball das hinterste Kind, läuft es nach vorn und setzt sich an die Spitze der Reihe. Welches Team hat als erstes die Linie überquert?","coach":["Ruhiger Abschluss, gut für das Schlusswort danach"],"var":"","d":{"s":"grass","items":[["A",14,24],["A",20,24],["A",26,24],["A",32,24],["A",38,24],["A",44,24,1],["B",14,42],["B",20,42],["B",26,42],["B",32,42],["B",38,42],["B",44,42,1],["pass",44,20,39,20],["pass",44,38,39,38],["run",12,28,50,28],["line",80],["txt",80,8,"Ziel"],["txt",30,56,"Ball über den Kopf nach hinten"]]},"videos":[]}'::jsonb),
  ('ex34', null, 'grass', 'ein', 'Dribbler', 'Karte E3', '{"src":"SFV Trainingskarten Kat. E, Training 3","org":"Zwei Teams, je ein markiertes Rechteck 25 × 5 m mit Markierungstellern. Die Hälfte eines Teams auf der einen Seite, die andere vis-à-vis.","offen":"Jedes Kind dribbelt mit einem Ball im Rechteck von der einen Seite zur anderen. Aufpassen, dass es keine Kollisionen gibt.","ueben":"Einen Markierungsteller andribbeln und einen Richtungswechsel ausführen, z. B. eine Runde mit Innenrist, Aussenrist, Übersteiger, hinter dem Standbein. Danach zum nächsten Teller und so fort. Anschliessend neu starten.","wett":"Ein Kind verteidigt auf der Linie, ein anderes im Viereck. Wer schafft es von der einen Seite zur anderen und umdribbelt beide Verteidiger?","coach":["Den Ball als Hund bei Fuss halten"],"var":"Engere Teller-Abstände machen es schwerer.","d":{"s":"grass","items":[["zone",4,6,92,18,""],["zone",4,40,92,18,""],["c",24,10],["c",38,20],["c",52,10],["c",66,20],["c",80,10],["c",24,44],["c",38,54],["c",52,44],["c",66,54],["c",80,44],["A",8,15,1],["A",92,15,1],["B",8,49,1],["B",92,49,1],["drib",11,15,36,18],["drib",89,15,68,18],["drib",11,49,36,52],["drib",89,49,68,52],["txt",50,33,"Richtungswechsel an jedem Teller"]]},"videos":[]}'::jsonb),
  ('ex35', null, 'grass', 'le', 'In die Endzone (3 gegen 3)', 'Karte E3', '{"src":"SFV Trainingskarten Kat. E, Training 3","org":"Feld 25 × 15 m mit einer Endzone an jedem Ende, mit flachen Markierungstellern gekennzeichnet. 3 gegen 3, Teams in Überziehern.","offen":"Spiel 3 gegen 3. Dribbelt Simon in die Endzone und kann den Ball dort stoppen, erhält sein Team 1 Punkt.","ueben":"Mutig nach vorne dribbeln und passen. In den Pausen das Freilaufen thematisieren: Der Ball ist die Sonne. Stehst du hinter einem Kind, bist du im Schatten und nicht anspielbar. Beweg dich ins Sonnenlicht!","wett":"Welches Team erzielt innerhalb von 5 Minuten mehr Tore?","coach":["Tipp: Die Endzone mit flachen und wenigen Markierungstellern kennzeichnen"],"var":"Einfacher: Endzone vergrössern, Joker einsetzen (für das Team in Ballbesitz anspielbar). Schwieriger: Endzone verkleinern.","d":{"s":"grass","items":[["zone",0,0,14,64,"Endzone"],["zone",86,0,14,64,"Endzone"],["A",30,20],["A",40,44],["A",56,28,1],["B",66,20],["B",64,42],["B",46,30],["drib",58,28,90,26],["run",40,44,74,50],["txt",50,62,"Aus dem Schatten in die Sonne"]]},"videos":[]}'::jsonb),
  ('ex36', null, 'grass', 'vi', 'Zügeln', 'Karte E3', '{"src":"SFV Trainingskarten Kat. E, Training 3","org":"Drei Posten im Feld 15 × 15 m: 1. Zügelmänner, 2. Linienkampf, 3. Eier legen (Reifen und Bälle).","ablauf":"1. Zügelmänner: Zwei Teams («Zügelmänner» und «Möbel»). Auf ein Signal bleiben die Möbel starr stehen, die Zügelmänner stossen sie so schnell wie möglich aus dem Feld, ohne dass sie umfallen. Die Möbel leisten Widerstand. 2 bis 4 Durchgänge, dann Rollenwechsel. 2. Linienkampf: Zwei Kinder halten sich an beiden Händen über einer Linie und versuchen, den Partner durch Ziehen und Stossen über die Linie zu bringen. Wer hat zuerst 3 Punkte? 3. Eier legen: Ein Kind verteidigt seinen Reifen (Nest), ein Angreifer versucht, seinen Ball (Ei) in den Reifen zu legen (nicht werfen). Bei Erfolg Rollenwechsel.","coach":["Fair kämpfen: stossen und ziehen, nicht schlagen","Partner regelmässig wechseln"],"var":"","d":{"s":"grass","items":[["area",8,6,40,30],["txt",12,12,"1"],["A",20,18],["B",24,20],["A",34,26],["B",38,24],["run",20,18,14,14],["txt",12,46,"2"],["A",22,52],["B",30,52],["txt",26,60,"Linie"],["txt",70,12,"3"],["hoop",76,26],["B",76,32],["A",86,20,1],["hoop",80,48],["B",74,50],["A",90,44,1],["run",86,22,79,26]]},"videos":[]}'::jsonb)
