-- =====================================================================
-- Trainer-App FC Seuzach · Update: Video-Links + SFV-Trainingskarten Kat. E
-- Einmal im Supabase SQL Editor ausführen (nach 01–04). Mehrfach ausführen ist ok.
-- =====================================================================

-- Eigene Video-Links pro Übung (z. B. YouTube), für alle Trainer der Mannschaft
create table if not exists exercise_links (
  id          uuid primary key default gen_random_uuid(),
  team_id     text not null references teams(id) on delete cascade,
  exercise_id text not null references exercises(id) on delete cascade,
  title       text not null,
  url         text not null check (url ~* '^https?://'),
  created_by  uuid default auth.uid(),
  created_at  timestamptz not null default now()
);
alter table exercise_links enable row level security;
drop policy if exists links_all on exercise_links;
create policy links_all on exercise_links for all using (is_member(team_id)) with check (is_member(team_id));

-- Übungen (Manual mit J+S-Videos, neu: SFV-Trainingskarten Kat. E)
on conflict (id) do update set data = excluded.data, name = excluded.name, page = excluded.page, phase = excluded.phase;

-- Vorlagen aus den SFV-Trainingskarten Kat. E
on conflict (id) do update set blocks = excluded.blocks, title = excluded.title, thema = excluded.thema;
